Bazooka_AutoCharge_Guard:
; CPY #$4E89: Boy actor only (independent of physical controller).
    db $C0, $89, $4E
; BNE original
    db $D0, $1C
; LDA $0ABA: equipped weapon index.
    db $AD, $BA, $0A
; CMP #$001A: Bazooka (also the native weapon-level routine exclusion).
    db $C9, $1A, $00
; BNE original
    db $D0, $14
; LDA $4EB7: Boy charge, $0400 = 100%.
    db $AD, $B7, $4E
; BMI stop: preserve negative cooldown values.
    db $30, $0B
; CMP #$0400
    db $C9, $00, $04
; BCC stop: ordinary recharge below 100% has already run.
    db $90, $06
; LDA #$0400
    db $A9, $00, $04
; STA $4EB7: normalize stale overcharge.
    db $8D, $B7, $4E
; stop:
; LDA #$0000: Z=1 skips automatic beyond-100% charge at $CF:CC7F.
    db $A9, $00, $00
; RTL
    db $6B
; original:
; JSL $F0:02D0: retain original controller/actor ownership test.
    db $22, $D0, $02, $F0
; RTL
    db $6B

